  const holdStart = i => PHASES.find(p => p.kind === 'hold' && p.i === i).t0;
  let t = T - RESET;          // the first run starts at the reset, so the first paint (the finished chart) clears first
  let last = 0, raf = 0, inView = false, paused = !autoplay, driving = false, resume = 0;
  let target = TOTAL, vel = 0, spin = 0, lastSpin = 0, dragging = false, seam = false;
  function render(time) { const s = stateAt(((time % T) + T) % T); draw(s.e, s.fade); target = s.e; if (s.i !== index) show(s.i); }
  const canRun = () => inView && !paused && !driving && !document.hidden && !reduce.matches;
  function frame(now) {
    if (!canRun()) { raf = 0; return; }
    t = (t + Math.min(100, now - last)) % T; last = now; render(t); raf = requestAnimationFrame(frame);
  }
  function kick() {
    if (!raf && canRun()) { cancelAnimationFrame(spin); spin = 0; vel = 0; last = performance.now(); raf = requestAnimationFrame(frame); }
  }
