  knob.addEventListener('pointerup', release, on);
  knob.addEventListener('pointercancel', release, on);
  svg.addEventListener('click', ev => {
    if (ev.target.closest('[data-tcl-knob]')) return;
    const { e, radius } = pointerE(ev, false);
    if (radius > .62 && radius < .86) goTo(nearest(e));      // a tap on the chart band
  }, on);
